<?php
/**
 * Plugin Name: Craftpixel Digital Storefront
 * Description: Premium digital catalog for Craftpixel. Checkout is disabled until explicitly enabled after verification.
 * Version: 1.0.0
 * License: GPL-2.0-or-later
 */
defined('ABSPATH') || exit;
final class Craftpixel_Digital_Storefront {
 const VERSION='1.0.0'; const GATE='CRAFTPIXEL_ENABLE_CHECKOUT';
 static function boot(){
  add_shortcode('craftpixel_store',array(__CLASS__,'render'));
  add_action('wp_enqueue_scripts',array(__CLASS__,'styles'));
  add_action('admin_notices',array(__CLASS__,'notice'));
  add_filter('woocommerce_is_purchasable',array(__CLASS__,'purchasable'),99,2);
  add_filter('woocommerce_variation_is_purchasable',array(__CLASS__,'purchasable'),99,2);
  add_filter('woocommerce_available_payment_gateways',array(__CLASS__,'gateways'),99);
  add_action('template_redirect',array(__CLASS__,'guard_checkout'));
 }
 static function enabled(){return defined(self::GATE)&&constant(self::GATE)===true;}
 static function styles(){wp_register_style('craftpixel-storefront',false,array(),self::VERSION);wp_add_inline_style('craftpixel-storefront',self::css());}
 static function notice(){
  if(!current_user_can('manage_options'))return;
  if(!class_exists('WooCommerce'))echo '<div class="notice notice-warning"><p><b>Craftpixel Storefront:</b> WooCommerce is not active. Add it through a supported deployment process before publishing products.</p></div>';
  if(!self::enabled())echo '<div class="notice notice-info"><p><b>Craftpixel safe launch:</b> checkout and purchasing are disabled. Verify MySQL/MariaDB, payment credentials, signed webhooks and protected downloads before enabling checkout.</p></div>';
 }
 static function purchasable($v,$product=null){return self::enabled()?$v:false;}
 static function gateways($v){return self::enabled()?$v:array();}
 static function guard_checkout(){
  if(self::enabled()||!function_exists('is_checkout')||!is_checkout()||is_wc_endpoint_url())return;
  wp_safe_redirect(home_url('/?craftpixel_checkout=unavailable'));exit;
 }
 static function render($atts=array()){
  if(!class_exists('WooCommerce'))return '<section class="cp-store cp-setup"><p class="cp-eye">CRAFTPIXEL / DIGITAL GOODS</p><h2>Your next great project starts here.</h2><p>The catalog is being prepared. WooCommerce and production MySQL/MariaDB are required before products can be published.</p></section>';
  wp_enqueue_style('craftpixel-storefront');
  $atts=shortcode_atts(array('per_page'=>12),$atts,'craftpixel_store');
  $limit=max(1,min(24,absint($atts['per_page'])));
  $search=isset($_GET['cp_search'])?sanitize_text_field(wp_unslash($_GET['cp_search'])):'';
  $cat=isset($_GET['cp_category'])?sanitize_title(wp_unslash($_GET['cp_category'])):'';
  $page=isset($_GET['cp_page'])?max(1,absint($_GET['cp_page'])):1;
  $args=array('status'=>'publish','limit'=>$limit,'page'=>$page,'paginate'=>true,'orderby'=>'date','order'=>'DESC','return'=>'objects');
  if($search!=='')$args['s']=$search;if($cat!=='')$args['category']=array($cat);
  $result=wc_get_products($args);$products=is_object($result)&&isset($result->products)?$result->products:array();
  $pages=is_object($result)&&isset($result->max_num_pages)?(int)$result->max_num_pages:1;
  $terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>true));
  ob_start(); ?>
  <div class="cp-store">
   <section class="cp-hero"><div><p class="cp-eye">THE CREATIVE TOOLKIT</p><h1>Good ideas deserve<br><em>great design.</em></h1><p class="cp-lead">Thoughtfully made templates, UI kits and design assets to help you ship your next big thing — beautifully and faster.</p><a class="cp-btn cp-dark" href="#cp-catalog">Explore the collection <span>↘</span></a><div class="cp-trust"><span>✳ Curated for creators</span><span>↗ Made to move projects forward</span></div></div>
    <div class="cp-art" role="img" aria-label="Abstract design preview collage"><div class="cp-art-paper"><small>STUDIO / 026</small><strong>Make space<br>for better<br>ideas.</strong><b>✳</b></div><div class="cp-art-orange"><div class="cp-browser">● ● ●</div><div class="cp-lines"></div><div class="cp-tiles"><i></i><i></i><i></i><i></i><i></i><i></i></div><small>DESIGN SYSTEM / 01</small></div><div class="cp-sticker">DESIGNED<br>TO CREATE ↗</div></div>
   </section>
   <section class="cp-benefits"><div><b>01</b> Made for real work</div><div><b>02</b> Easy to customize</div><div><b>03</b> Digital-first resources</div></section>
   <section class="cp-catalog" id="cp-catalog"><div class="cp-heading"><div><p class="cp-eye">THE COLLECTION</p><h2>Find your next <em>favorite.</em></h2></div><span><?php echo esc_html((string)count($products)); ?> items</span></div>
    <form class="cp-filters" method="get" action="<?php echo esc_url(get_permalink()); ?>"><label class="screen-reader-text" for="cp-search">Search products</label><input id="cp-search" name="cp_search" type="search" value="<?php echo esc_attr($search); ?>" placeholder="Search templates, UI kits, assets…"><label class="screen-reader-text" for="cp-category">Category</label><select id="cp-category" name="cp_category"><option value="">All collections</option><?php if(!is_wp_error($terms))foreach($terms as $term):?><option value="<?php echo esc_attr($term->slug);?>" <?php selected($cat,$term->slug);?>><?php echo esc_html($term->name);?></option><?php endforeach;?></select><button class="cp-btn cp-dark" type="submit">Find products ↗</button></form>
    <?php if(!$products):?><div class="cp-empty"><span>✳</span><h3>A little more inspiration, coming soon.</h3><p>Publish products in WooCommerce and they will appear here automatically.</p></div><?php else:?><div class="cp-grid"><?php foreach($products as $product):if(!$product instanceof WC_Product)continue;?><article class="cp-product"><a class="cp-visual" href="<?php echo esc_url(get_permalink($product->get_id()));?>"><?php echo wp_kses_post($product->get_image('woocommerce_thumbnail',array('loading'=>'lazy')));?><span>↗</span></a><div class="cp-meta"><span><?php echo wp_kses_post(wc_get_product_category_list($product->get_id(),', ')?:'Digital design');?></span><span>DIGITAL RESOURCE</span></div><h3><a href="<?php echo esc_url(get_permalink($product->get_id()));?>"><?php echo esc_html($product->get_name());?></a></h3><div class="cp-product-bottom"><span><?php echo wp_kses_post($product->get_price_html());?></span><a href="<?php echo esc_url(get_permalink($product->get_id()));?>">Explore details ↗</a></div></article><?php endforeach;?></div>
    <?php if($pages>1):?><nav class="cp-pages" aria-label="Catalog pages"><?php for($n=1;$n<=$pages;$n++):?><a href="<?php echo esc_url(add_query_arg(array('cp_page'=>$n,'cp_search'=>$search,'cp_category'=>$cat),get_permalink()));?>" <?php echo $page===$n?'aria-current="page"':'';?>><?php echo esc_html((string)$n);?></a><?php endfor;?></nav><?php endif;endif;?>
   </section><section class="cp-cta"><p class="cp-eye">MAKE IT YOURS</p><h2>Less time setting up.<br><em>More time creating.</em></h2><p>Useful creative resources, without the blank-canvas feeling.</p><a class="cp-btn cp-lime" href="#cp-catalog">Browse the collection ↗</a></section>
   <footer class="cp-footer"><a class="cp-logo" href="<?php echo esc_url(home_url('/'));?>">craftpixel<span>®</span></a><span>Good design moves you forward.</span><a href="#cp-catalog">Back to top ↑</a></footer><?php if(!self::enabled()):?><p class="cp-launch">PRE-LAUNCH CATALOG · SECURE CHECKOUT IS NOT ENABLED</p><?php endif;?>
  </div><?php return ob_get_clean();
 }
 static function css(){return <<<'CSS'
.cp-store{--ink:#20211e;--muted:#77796f;--paper:#f7f6f1;--line:#e3e2da;--lime:#d7f36b;color:var(--ink);background:#fff;font:15px/1.55 Inter,system-ui,-apple-system,"Segoe UI",sans-serif;overflow:hidden}.cp-store *{box-sizing:border-box}.cp-store a{color:inherit;text-decoration:none}.cp-store .cp-eye{font-size:10px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:#686b5e;margin:0 0 18px}.cp-store .cp-hero{display:grid;grid-template-columns:1fr 1fr;min-height:510px;background:var(--paper);padding:clamp(30px,6vw,82px);gap:35px;align-items:center}.cp-store h1{font-size:clamp(43px,6vw,76px);line-height:.99;letter-spacing:-.065em;font-weight:650;margin:0 0 24px}.cp-store h1 em,.cp-store h2 em{font-family:Georgia,serif;font-weight:400;letter-spacing:-.055em}.cp-store .cp-lead{max-width:410px;color:#62645b;font-size:16px;margin:0 0 28px}.cp-store .cp-btn{display:inline-flex;align-items:center;justify-content:center;gap:26px;padding:14px 19px;font-size:12px;font-weight:750;border:0;border-radius:3px;cursor:pointer}.cp-store .cp-dark{background:#22241f;color:white}.cp-store .cp-trust{display:flex;gap:20px;flex-wrap:wrap;margin-top:38px;font-size:10px;color:#72746b}.cp-store .cp-art{position:relative;min-height:345px;background:#d9e1ce;border-radius:4px;overflow:hidden;display:flex;align-items:center;justify-content:center}.cp-store .cp-art-paper{position:absolute;background:#f9f6ed;width:56%;height:67%;left:9%;top:13%;padding:20px;transform:rotate(-7deg);box-shadow:0 18px 50px #31362a20;z-index:2}.cp-store .cp-art-paper small,.cp-store .cp-art-orange small{font-size:8px;letter-spacing:.15em}.cp-store .cp-art-paper strong{display:block;font-size:clamp(25px,3vw,40px);line-height:.98;letter-spacing:-.06em;margin-top:27px}.cp-store .cp-art-paper b{position:absolute;right:18px;bottom:14px;font-size:25px}.cp-store .cp-art-orange{position:absolute;background:#f0a98c;width:43%;height:62%;right:7%;bottom:8%;padding:14px;transform:rotate(8deg)}.cp-store .cp-browser{font-size:8px}.cp-store .cp-lines{height:24%;margin-top:18px;background:repeating-linear-gradient(to bottom,transparent 0 7px,#393a32 8px 9px)}.cp-store .cp-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:10px}.cp-store .cp-tiles i{height:28px;background:#f8e6d8}.cp-store .cp-tiles i:nth-child(2){background:#d8f06b}.cp-store .cp-tiles i:nth-child(3){background:#32372c}.cp-store .cp-tiles i:nth-child(5){background:#32372c}.cp-store .cp-art-orange small{display:block;margin-top:8px}.cp-store .cp-sticker{position:absolute;z-index:3;right:5%;top:7%;background:var(--lime);border-radius:50%;width:88px;height:88px;display:grid;place-content:center;text-align:center;font-size:9px;font-weight:850;line-height:1.2;transform:rotate(9deg)}.cp-store .cp-benefits{display:grid;grid-template-columns:repeat(3,1fr);padding:24px clamp(25px,6vw,82px);border-bottom:1px solid var(--line);gap:20px;font-size:12px;font-weight:650}.cp-store .cp-benefits b{font-size:10px;color:#929487;margin-right:12px}.cp-store .cp-catalog{padding:78px clamp(25px,6vw,82px)}.cp-store .cp-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:26px}.cp-store .cp-heading .cp-eye{margin-bottom:10px}.cp-store h2{font-size:clamp(31px,4vw,48px);letter-spacing:-.06em;line-height:1.05;margin:0;font-weight:650}.cp-store .cp-heading>span{font-size:11px;color:var(--muted)}.cp-store .cp-filters{display:grid;grid-template-columns:1fr 210px auto;gap:10px;margin-bottom:30px}.cp-store .cp-filters input,.cp-store .cp-filters select{min-width:0;border:1px solid var(--line);background:#fff;border-radius:3px;padding:13px 14px;color:var(--ink);font:inherit;font-size:12px}.cp-store .cp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:35px 20px}.cp-store .cp-visual{display:flex;position:relative;aspect-ratio:1.12;background:#f2f0e9;align-items:center;justify-content:center;overflow:hidden}.cp-store .cp-visual img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .35s}.cp-store .cp-visual:hover img{transform:scale(1.035)}.cp-store .cp-visual>span{position:absolute;right:12px;top:12px;width:32px;height:32px;background:white;border-radius:50%;display:grid;place-items:center}.cp-store .cp-meta{display:flex;justify-content:space-between;gap:8px;margin-top:15px;color:#797b71;font-size:9px;text-transform:uppercase;letter-spacing:.06em}.cp-store .cp-product h3{font-size:17px;letter-spacing:-.035em;font-weight:650;margin:7px 0 12px}.cp-store .cp-product-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--line);padding-top:12px;font-size:12px;font-weight:750}.cp-store .cp-product-bottom a{font-size:10px}.cp-store .cp-empty{text-align:center;background:var(--paper);padding:70px 20px}.cp-store .cp-empty>span{font-size:28px}.cp-store .cp-empty h3{font-size:22px;letter-spacing:-.04em;margin:14px 0 8px}.cp-store .cp-empty p,.cp-store .cp-cta p:not(.cp-eye){font-size:12px;color:var(--muted);margin:0}.cp-store .cp-pages{display:flex;gap:8px;justify-content:center;margin-top:36px}.cp-store .cp-pages a{border:1px solid var(--line);padding:8px 12px;font-size:12px}.cp-store .cp-pages a[aria-current=page]{background:var(--ink);color:white}.cp-store .cp-cta{background:#252720;color:#f7f6f1;padding:70px 25px;text-align:center}.cp-store .cp-cta .cp-eye{color:var(--lime)}.cp-store .cp-cta h2{font-size:clamp(34px,5vw,56px)}.cp-store .cp-cta p:not(.cp-eye){color:#c1c2b9;margin:18px 0 25px}.cp-store .cp-lime{background:var(--lime);color:#20211e}.cp-store .cp-footer{display:flex;justify-content:space-between;align-items:center;padding:24px clamp(25px,6vw,82px);gap:18px;font-size:10px;color:var(--muted)}.cp-store .cp-logo{font-size:20px;font-weight:850;letter-spacing:-.08em;color:var(--ink)}.cp-store .cp-logo span{font-size:9px;vertical-align:top;letter-spacing:0}.cp-store .cp-launch{text-align:center;background:var(--paper);margin:0;padding:10px;font-size:9px;letter-spacing:.12em;color:var(--muted)}.cp-store .cp-setup{padding:65px 30px;background:var(--paper);text-align:center}.cp-store .cp-setup h2{font-size:clamp(30px,5vw,48px);margin-bottom:14px}.cp-store .cp-setup>p:last-child{max-width:540px;margin:0 auto;color:var(--muted);font-size:13px}@media(max-width:760px){.cp-store .cp-hero{grid-template-columns:1fr;padding:35px 23px}.cp-store .cp-art{min-height:300px}.cp-store .cp-benefits{padding:20px 23px;gap:12px;font-size:10px}.cp-store .cp-catalog{padding:55px 23px}.cp-store .cp-heading{align-items:flex-start;flex-direction:column}.cp-store .cp-filters{grid-template-columns:1fr 1fr}.cp-store .cp-filters input,.cp-store .cp-filters .cp-btn{grid-column:1/-1}.cp-store .cp-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:27px 12px}.cp-store .cp-meta{flex-direction:column;gap:3px}.cp-store .cp-product h3{font-size:15px}.cp-store .cp-product-bottom{align-items:flex-start;flex-direction:column;gap:6px}.cp-store .cp-footer{flex-wrap:wrap}.cp-store .cp-footer>span{order:3;width:100%}}@media(max-width:420px){.cp-store .cp-grid{grid-template-columns:1fr}.cp-store .cp-meta,.cp-store .cp-product-bottom{flex-direction:row;align-items:center}}
CSS;}
}
Craftpixel_Digital_Storefront::boot();
